using System;
using System.Collections.Generic;
using System.Linq;

namespace Polypiler.Core.Verification.Running;

/// <summary>Where the code a plan runs came from (PRD §13.3).</summary>
public enum TrustLevel {

  /// <summary>Written or generated by the project itself; it may run on a host that only limits it.</summary>
  Trusted,

  /// <summary>Came from outside; it runs only where the sandbox isolates it.</summary>
  Untrusted

}

/// <summary>
/// Everything one run does: the files its directory starts with, the build steps in order, the step
/// that executes the result, the limits each step is held to, and how far its code is trusted.
/// </summary>
/// <param name="Files">The files of the working directory, by name relative to it, with their bytes.</param>
/// <param name="Build">The build steps, run in order; the first that fails ends the run.</param>
/// <param name="Execute">The step that runs what the build produced; its output is the run's output.</param>
/// <param name="Limits">The limits of each step.</param>
/// <param name="Trust">Where the code came from.</param>
public sealed record RunPlan(IReadOnlyDictionary<string, ReadOnlyMemory<byte>> Files, IReadOnlyList<ProcessSpec> Build, ProcessSpec Execute, RunLimits Limits, TrustLevel Trust) {

  /// <summary>The files of the working directory, by name relative to it, with their bytes.</summary>
  /// <exception cref="ArgumentException">A name is empty, absolute, or contains a <c>..</c> segment.</exception>
  public IReadOnlyDictionary<string, ReadOnlyMemory<byte>> Files { get; } = CheckFiles(Files);

  /// <summary>The build steps, run in order.</summary>
  public IReadOnlyList<ProcessSpec> Build { get; } = Build?.ToArray() ?? throw new ArgumentNullException(nameof(Build));

  /// <summary>The step that runs what the build produced.</summary>
  public ProcessSpec Execute { get; } = Execute ?? throw new ArgumentNullException(nameof(Execute));

  /// <summary>The limits of each step.</summary>
  public RunLimits Limits { get; } = Limits ?? throw new ArgumentNullException(nameof(Limits));

  /// <summary>The steps in the order they run: the build steps, then the execute step.</summary>
  public IEnumerable<ProcessSpec> Steps => this.Build.Append(this.Execute);

  /// <summary>Whether a name stays inside the directory it is relative to: not empty, not rooted, without a <c>..</c> segment.</summary>
  /// <param name="name">The name, with <c>/</c> or <c>\</c> between its segments.</param>
  public static bool IsRelativeName(string name)
    => name.Length > 0
       && name[0] is not ('/' or '\\')
       && !(name.Length >= 2 && char.IsAsciiLetter(name[0]) && name[1] == ':')
       && !name.Split('/', '\\').Contains("..");

  private static Dictionary<string, ReadOnlyMemory<byte>> CheckFiles(IReadOnlyDictionary<string, ReadOnlyMemory<byte>> files) {
    ArgumentNullException.ThrowIfNull(files);
    foreach (var name in files.Keys)
      if (!IsRelativeName(name))
        throw new ArgumentException($"the file name '{name}' leaves the working directory: only relative names without '..' are allowed", nameof(files));

    return new(files, StringComparer.Ordinal);
  }

}
